<template><main class="admin-content"><div class="mb-6 flex flex-wrap items-end justify-between gap-3"><div><p class="text-xs font-black uppercase tracking-wider text-emerald-600">Accounting</p><h1 class="text-3xl font-black">Cash Flow & Forecasting</h1><p class="text-slate-500">See expected money in, bills out and your projected cash position.</p></div><NuxtLink class="btn-secondary" to="/admin/accounting">← Accounting</NuxtLink></div>
<div v-if="err" class="mb-4 rounded-lg bg-red-50 p-3 text-red-700">{{err}}</div>
<section class="admin-panel p-5"><div class="flex flex-wrap items-center gap-3"><b>Forecast:</b><button v-for="d in [30,60,90,180]" :key="d" class="btn-secondary" :class="days===d?'ring-2 ring-emerald-400':''" @click="days=d;load()">{{d}} days</button><button class="btn-secondary ml-auto" @click="load">Refresh</button></div><div class="mt-4 grid gap-3 sm:grid-cols-2 lg:grid-cols-4 xl:grid-cols-7"><div class="metric"><small>Current Cash</small><b>{{money(data.opening_balance)}}</b></div><div class="metric"><small>Expected In</small><b class="text-emerald-700">{{money(data.summary?.expected_in)}}</b></div><div class="metric"><small>Expected Out</small><b class="text-red-600">{{money(data.summary?.expected_out)}}</b></div><div class="metric"><small>Projected Cash</small><b :class="num(data.summary?.projected_balance)<0?'text-red-600':'text-emerald-700'">{{money(data.summary?.projected_balance)}}</b></div><div class="metric"><small>Lowest Point</small><b :class="num(data.summary?.lowest_balance)<0?'text-red-600':''">{{money(data.summary?.lowest_balance)}}</b></div><div class="metric"><small>Overdue In</small><b>{{money(data.summary?.overdue_in)}}</b></div><div class="metric"><small>Overdue Out</small><b>{{money(data.summary?.overdue_out)}}</b></div></div>
<div class="mt-6 rounded-xl border p-4"><h2 class="text-lg font-black">Weekly Cash Forecast</h2><div class="mt-4 flex h-52 items-end gap-2 overflow-x-auto"><div v-for="w in adjustedBuckets" :key="w.start" class="flex h-full min-w-16 flex-1 flex-col justify-end"><div class="flex flex-1 items-end justify-center gap-1"><div class="w-2/5 rounded-t bg-emerald-300" :style="{height:height(w.inflow)}" :title="`In ${money(w.inflow)}`"></div><div class="w-2/5 rounded-t bg-red-300" :style="{height:height(w.outflow)}" :title="`Out ${money(w.outflow)}`"></div></div><span class="mt-2 text-center text-[10px] font-bold">{{shortDate(w.start)}}</span></div></div><div class="mt-3 flex gap-4 text-xs"><span>🟩 Money in</span><span>🟥 Money out</span></div></div></section>
<section class="mt-5 grid gap-5 xl:grid-cols-3"><div class="admin-panel p-5 xl:col-span-2"><div class="flex items-center justify-between"><div><h2 class="text-xl font-black">Forecast Timeline</h2><p class="text-sm text-slate-500">Invoices, supplier bills, purchase orders and recurring forecast items.</p></div></div><div class="mt-4 overflow-x-auto"><table class="w-full text-sm"><thead><tr class="border-b text-left"><th class="p-2">Date</th><th>Item</th><th>Type</th><th class="text-right">Movement</th><th class="text-right">Projected Cash</th></tr></thead><tbody><tr v-for="x in adjustedEvents" :key="`${x.type}-${x.source_id}-${x.date}`" class="border-b"><td class="p-2 whitespace-nowrap">{{date(x.date)}}</td><td><b>{{x.label}}</b><span v-if="x.overdue" class="ml-2 rounded bg-red-100 px-2 py-0.5 text-xs font-bold text-red-700">Overdue</span></td><td class="capitalize">{{x.type.replace('_',' ')}}</td><td class="text-right font-bold" :class="x.amount>=0?'text-emerald-700':'text-red-600'">{{signed(x.amount)}}</td><td class="text-right font-bold">{{money(x.projected_balance)}}</td></tr><tr v-if="!adjustedEvents.length"><td colspan="5" class="p-6 text-center text-slate-500">No forecast transactions in this period.</td></tr></tbody></table></div></div>
<div class="space-y-5"><div class="admin-panel p-5"><h2 class="text-xl font-black">What If?</h2><p class="text-sm text-slate-500">Model a temporary transaction without changing accounting records.</p><div class="mt-4 space-y-3"><input v-model="scenario.name" class="field" placeholder="e.g. New stock purchase"><div class="grid grid-cols-2 gap-2"><select v-model="scenario.direction" class="field"><option value="outflow">Money out</option><option value="inflow">Money in</option></select><input v-model.number="scenario.amount" type="number" min="0" step="0.01" class="field" placeholder="Amount"></div><input v-model="scenario.date" type="date" class="field"><button class="btn-primary w-full" @click="applyScenario">Apply Scenario</button><button v-if="whatIf" class="btn-secondary w-full" @click="whatIf=null">Clear Scenario</button></div><div v-if="whatIf" class="mt-4 rounded-lg bg-amber-50 p-3 text-sm"><b>Scenario active:</b> {{whatIf.name}} {{signed(whatIf.amount)}} on {{date(whatIf.date)}}. This is not saved.</div></div>
<div class="admin-panel p-5"><h2 class="text-xl font-black">Recurring / Planned Items</h2><form class="mt-4 space-y-2" @submit.prevent="saveItem"><input v-model="form.name" required class="field" placeholder="Hosting, insurance, rent..."><div class="grid grid-cols-2 gap-2"><select v-model="form.direction" class="field"><option value="outflow">Money out</option><option value="inflow">Money in</option></select><input v-model.number="form.amount" required type="number" min="0" step="0.01" class="field" placeholder="Amount"></div><div class="grid grid-cols-2 gap-2"><input v-model="form.start_date" required type="date" class="field"><select v-model="form.frequency" class="field"><option value="once">Once</option><option value="weekly">Weekly</option><option value="fortnightly">Fortnightly</option><option value="monthly">Monthly</option><option value="quarterly">Quarterly</option><option value="yearly">Yearly</option></select></div><button class="btn-primary w-full">Add Forecast Item</button></form><div v-for="x in items" :key="x.id" class="mt-3 flex items-center justify-between gap-2 border-t pt-3 text-sm"><div><b>{{x.name}}</b><div class="text-xs text-slate-500">{{money(x.amount)}} · {{x.frequency}} · {{date(x.start_date)}}</div></div><button class="text-xs font-bold text-red-600" @click="removeItem(x.id)">Delete</button></div></div></div></section></main></template>
<script setup lang="ts">definePageMeta({layout:'admin',middleware:['admin']});const{adminFetch,isSuperAdmin}=useAdminFetch();const days=ref(90),data=ref<any>({summary:{},events:[],buckets:[],banks:[]}),items=ref<any[]>([]),err=ref(''),whatIf=ref<any>(null);const today=new Date().toISOString().slice(0,10);const form=reactive({name:'',direction:'outflow',amount:null as any,start_date:today,frequency:'monthly'});const scenario=reactive({name:'',direction:'outflow',amount:null as any,date:today});const num=(v:any)=>Number(v||0),money=(v:any)=>new Intl.NumberFormat('en-AU',{style:'currency',currency:'AUD'}).format(num(v)),date=(v:any)=>v?new Date(String(v)+'T00:00:00').toLocaleDateString('en-AU'):'—',shortDate=(v:any)=>new Date(String(v)+'T00:00:00').toLocaleDateString('en-AU',{day:'numeric',month:'short'}),signed=(v:any)=>`${num(v)>=0?'+':'−'}${money(Math.abs(num(v)))}`;
const adjustedEvents=computed(()=>{const a=[...(data.value.events||[]).map((x:any)=>({...x}))];if(whatIf.value)a.push({...whatIf.value,type:'what_if',source_id:'scenario'});a.sort((x:any,y:any)=>x.date.localeCompare(y.date));let run=num(data.value.opening_balance);return a.map((x:any)=>{run+=num(x.amount);return{...x,projected_balance:run}})});const adjustedBuckets=computed(()=>{const b=(data.value.buckets||[]).map((x:any)=>({...x}));if(whatIf.value){const z=b.find((x:any)=>whatIf.value.date>=x.start&&whatIf.value.date<=x.end);if(z){if(whatIf.value.amount>=0)z.inflow+=whatIf.value.amount;else z.outflow+=Math.abs(whatIf.value.amount);z.net=z.inflow-z.outflow}}return b});const chartMax=computed(()=>Math.max(1,...adjustedBuckets.value.flatMap((x:any)=>[x.inflow,x.outflow]))),height=(v:any)=>`${Math.max(2,Math.round(num(v)/chartMax.value*100))}%`;
async function load(){err.value='';try{if(!isSuperAdmin.value)return navigateTo('/admin');[data.value,items.value]=await Promise.all([adminFetch(`/api/admin/accounting/cash-flow/forecast?days=${days.value}`),adminFetch('/api/admin/accounting/cash-flow/items')])}catch(e:any){err.value=e?.data?.statusMessage||e.message}}async function saveItem(){try{await adminFetch('/api/admin/accounting/cash-flow/items',{method:'POST',body:form});form.name='';form.amount=null;await load()}catch(e:any){err.value=e?.data?.statusMessage||e.message}}async function removeItem(id:number){if(!confirm('Delete this forecast item?'))return;await adminFetch(`/api/admin/accounting/cash-flow/items?id=${id}`,{method:'DELETE'});await load()}function applyScenario(){if(!scenario.name||!num(scenario.amount)||!scenario.date)return;whatIf.value={name:scenario.name,label:scenario.name,date:scenario.date,amount:scenario.direction==='inflow'?num(scenario.amount):-num(scenario.amount)}}onMounted(load);</script>
<style scoped>.admin-panel{@apply rounded-xl border border-slate-200 bg-white shadow-sm}.metric{@apply flex min-h-24 flex-col rounded-xl border border-slate-200 bg-slate-50 p-4}.metric small{@apply text-xs font-black uppercase tracking-wide text-slate-500}.metric b{@apply mt-2 text-xl font-black}.field{@apply w-full rounded-lg border border-slate-300 bg-white px-3 py-2 text-sm}.btn-primary{@apply rounded-lg bg-slate-900 px-4 py-2 text-sm font-bold text-white}.btn-secondary{@apply rounded-lg border border-slate-300 bg-white px-4 py-2 text-sm font-bold}</style>
